import {
  Code,
  DocsSection,
  SectionHeader,
  type ImperativeHandleMetadata
} from "react-lib-tools";

/**
 * Lists the methods of an imperative API (generated by `compileDocs`) as a section of a page.
 * Use this instead of `ImperativeHandle` on pages that document more than one thing,
 * since `ImperativeHandle` renders its own page title.
 * Markup mirrors react-lib-tools' `ImperativeHandle` so the two look the same.
 */
export function Methods({
  idPrefix = "",
  json
}: {
  /** Prefix for the methods' element ids (e.g. if the page also documents a prop or option with the same name). */
  idPrefix?: string;
  json: unknown;
}) {
  const { description, methods } = json as ImperativeHandleMetadata;

  return (
    <>
      <SectionHeader>Methods</SectionHeader>
      <DocsSection
        sections={description.filter((section) => section.content)}
      />
      <dl className="flex flex-col">
        {methods.map((method) => (
          <div
            className="py-5 border-t border-ink/10 first:border-t-0 first:pt-0"
            key={method.name}
          >
            <dt
              className="[&_code]:text-sky-700 dark:[&_code]:text-sky-300 text-lg font-bold"
              data-toc="1"
              id={idPrefix + method.name}
            >
              {method.name}
            </dt>
            <dd className="mt-2">
              <DocsSection sections={method.description} />
              <Code className="mt-2 p-2 flex flex-col" html={method.html} />
            </dd>
          </div>
        ))}
      </dl>
    </>
  );
}
